getSrcList()
   {
	   SET usrBaseDir = $$$USRBASEDIR _ $username
	   SET svnBaseDir = usrBaseDir _ $$$SVNBASEDIR
	   SET fullPath = svnBaseDir _ $$$SVNTRUNK _ "cls/" _ $NAMESPACE
	   set passwd = "aal5esh9"
	   write !, fullPath
	   set file = usrBaseDir _ "/tempSvnList"
 	Set cmd = $$$SVNLIST _ " --username " _ $username _ " --password " _ passwd _ " " _ fullPath _ " > " _ file
	Set stat = $ZF(-1, cmd)
    write !, cmd _ " : " _ stat

    Set filesList= ##class(%Library.ListOfDataTypes).%New()

	Set file=##class(%File).%New(file)
	Write !, "File size:" _ file.Size
	Do file.Open("RS")

    While 'file.AtEnd 
    { 
     set ln = file.ReadLine(,.sc,.eol) 
     If $$$ISERR(sc) 
     { Write !, "ERROR" Quit } 
     elseIf eol 
     { Write !, "EOF " _ eol} 
     else
     {
	    write !, "Line: " _ ln
	    if ( $LENGTH(ln) > 1)
	    {
		    DO filesList.Insert( fullPath _ "/" _ ln)
	    }
     }
    }


    /*

    Set EOF=0 Do {
	     Use InFile
	     Read InRecord
	     If $ZEOF=-1 Set EOF=1 Quit
	    // Use 0 Write !,InRecord
	     DO filesList.Insert( fullPath _ "/" _ InRecord)
	     SET count=count+1

    }While EOF=0


  */
  Quit filesList
   }

getItems(filesList) [xName, xTime, iName, fTime, xCmt, SQLCODE]
{
	&sql(Declare C2 Cursor for
		Select FileName, InternalName, ClassModifiedTime, FileModifiedTime, Comment 
		Into :xName, :iName, :xTime,  :fTime, :xCmt
		From ITFCOMMON.SrcCtrlInfo)

	Set SQLCODE=0  &sql(OPEN C2) 
	WHILE(SQLCODE = 0)
	{
		 &sql(FETCH C2)  
	     // Write !, "SQL code:" , SQLCODE
	     Quit:SQLCODE 



   set found = filesList.Find(xName)
   if (found)
   {
	     write !, found _ " Name: " _ xName _ " " _ iName _ ", Time: " _ xTime _  " " _ fTime _ ", comment: " _ xCmt
	     do filesList.RemoveAt(found)    
   }
   else
   {
	   write !, "Not in SVN: " _ xName
   }

	}
	 &sql(CLOSE C2)
	  set key = filesList.Next("")
	  while(key >= 1)
	  {
		  write !, "In svn:" _ filesList.GetAt(key)
		  set key = filesList.Next(key)
	  }
}

deleteItems() [SQLCODE]
 {
  Set Empty = ""
  &sql(DELETE FROM ITFCOMMON.SrcCtrlInfo)
     //  WHERE FileName IS NULL)
    IF SQLCODE=0 {
    WRITE !,"Delete succeeded"
    WRITE !,"Row count=",%ROWCOUNT
    WRITE !,"Row ID=",%ROWID }
    ELSE {
    WRITE !,"Delete failed, SQLCODE=",SQLCODE }
 }

